CREATE OR REPLACE FUNCTION private.current_user_can_edit_site_visit(p_company_id text, p_opportunity_id uuid, p_project_id text, p_project_ref uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_actor_user_id uuid := private.get_current_user_id();
  v_project_id uuid := coalesce(p_project_ref, private.try_parse_uuid(p_project_id));
begin
  if private.try_parse_uuid(p_company_id) is distinct from private.get_user_company_id() then
    return false;
  end if;
  if p_opportunity_id is not null
    and (p_project_id is not null or p_project_ref is not null)
    and (
      v_project_id is null
      or (
        p_project_id is not null
        and p_project_ref is not null
        and private.try_parse_uuid(p_project_id) is distinct from p_project_ref
      )
      or not private.opportunity_project_relationship_is_valid(
        private.try_parse_uuid(p_company_id),
        p_opportunity_id,
        v_project_id
      )
    )
  then
    return false;
  end if;
  if p_opportunity_id is null and v_project_id is null then
    return true;
  end if;
  return (p_opportunity_id is not null and private.user_can_edit_opportunity(
      v_actor_user_id, p_opportunity_id
    ))
    or (v_project_id is not null
      and private.user_can_view_project(v_actor_user_id, v_project_id)
      and private.user_can_edit_project(v_actor_user_id, v_project_id));
end;
$function$

CREATE OR REPLACE FUNCTION private.current_user_can_view_site_visit(p_company_id text, p_opportunity_id uuid, p_project_id text, p_project_ref uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_actor_user_id uuid := private.get_current_user_id();
  v_project_id uuid := coalesce(p_project_ref, private.try_parse_uuid(p_project_id));
begin
  if private.try_parse_uuid(p_company_id) is distinct from private.get_user_company_id() then
    return false;
  end if;
  if p_opportunity_id is null and v_project_id is null then
    return true;
  end if;
  return (p_opportunity_id is not null and private.user_can_view_opportunity(
      v_actor_user_id, p_opportunity_id
    ))
    or (v_project_id is not null and private.user_can_view_project(
      v_actor_user_id, v_project_id
    ));
end;
$function$

CREATE OR REPLACE FUNCTION private.enforce_site_visit_status_monotonicity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
begin
  if old.status::text in ('completed', 'cancelled')
     and new.status is distinct from old.status then
    raise exception 'site_visit_terminal_status_is_monotonic'
      using errcode = '55000';
  end if;
  if old.status::text = 'in_progress' and new.status::text = 'scheduled' then
    raise exception 'site_visit_status_cannot_regress'
      using errcode = '55000';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_google_calendar_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_connection_id uuid;
  v_operation     text;
  v_company_text  text;
  v_company_uuid  uuid;
begin
  -- Only booked appointments sync to Google. Walk-up captures and legacy rows
  -- (booked_at IS NULL) have meaningless scheduled_at values and must stay off
  -- every calendar surface.
  if coalesce(new.booked_at, old.booked_at) is null then
    return coalesce(new, old);
  end if;

  v_company_text := btrim(coalesce(new.company_id, old.company_id));
  if v_company_text is null or v_company_text = '' then
    return coalesce(new, old);
  end if;

  -- The queue is uuid-keyed; a malformed legacy tenant id must never abort the
  -- caller's write, so the cast failing is a no-op, not an error.
  begin
    v_company_uuid := v_company_text::uuid;
  exception when others then
    return coalesce(new, old);
  end;

  if tg_op = 'INSERT' then
    v_operation := 'create';
  elsif new.deleted_at is not null and old.deleted_at is null then
    v_operation := 'delete';
  elsif new.status = 'cancelled' and old.status is distinct from 'cancelled' then
    v_operation := 'delete';
  elsif new.scheduled_at is distinct from old.scheduled_at
     or new.duration_minutes is distinct from old.duration_minutes
     or new.notes is distinct from old.notes then
    -- Only schedule-visible changes are worth a Google write. Photos,
    -- measurements and internal notes never reach the calendar.
    v_operation := 'update';
  else
    return new;
  end if;

  if v_operation <> 'delete' and coalesce(new.scheduled_at, old.scheduled_at) is null then
    return coalesce(new, old);
  end if;

  -- A newly created visit is never queued as already-cancelled or deleted.
  if tg_op = 'INSERT' and (new.status = 'cancelled' or new.deleted_at is not null) then
    return new;
  end if;

  -- The mailbox whose calendar this lands on. Only a connection that actually
  -- granted the calendar scope is eligible; with none, nothing is queued and
  -- the feature is simply inert for that company.
  select ec.id
    into v_connection_id
    from public.email_connections ec
   where ec.company_id = v_company_text
     and ec.status = 'active'
     and ec.granted_scopes && array[
           'https://www.googleapis.com/auth/calendar.events',
           'https://www.googleapis.com/auth/calendar'
         ]
   order by ec.created_at
   limit 1;

  if v_connection_id is null then
    return coalesce(new, old);
  end if;

  insert into public.google_calendar_sync_queue (
    company_id, connection_id, site_visit_id, operation,
    google_calendar_id, google_calendar_event_id, status
  )
  values (
    v_company_uuid,
    v_connection_id,
    coalesce(new.id, old.id),
    v_operation,
    coalesce(new.google_calendar_id, old.google_calendar_id),
    coalesce(new.google_calendar_event_id, old.google_calendar_event_id),
    'pending'
  )
  on conflict (site_visit_id, operation) where status = 'pending'
  do update set
    google_calendar_event_id = excluded.google_calendar_event_id,
    google_calendar_id       = excluded.google_calendar_id,
    next_attempt_at          = now(),
    updated_at               = now();

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_site_visit_opportunity_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_old_opportunity_id uuid := old.opportunity_id;
  v_new_opportunity_id uuid := new.opportunity_id;
  v_consumed boolean;
  v_actor_user_id uuid;
  v_company_id uuid;
  v_target public.opportunities%rowtype;
begin
  if v_old_opportunity_id is not distinct from v_new_opportunity_id then
    return new;
  end if;

  -- Path 1: minted token (admin/RPC flows) — identical semantics to
  -- private.guard_opportunity_child_reparent.
  delete from private.opportunity_child_reparent_tokens token
   where token.transaction_id = txid_current()
     and token.backend_pid = pg_backend_pid()
     and token.table_name = tg_table_name
     and token.row_id = old.id
     and token.old_opportunity_id is not distinct from v_old_opportunity_id
     and token.new_opportunity_id is not distinct from v_new_opportunity_id
  returning true into v_consumed;
  if found and coalesce(v_consumed, false) then
    return new;
  end if;

  -- Path 2: permission-checked change on a LIVE visit. Completed/cancelled
  -- visits are frozen evidence — token-only.
  if old.completed_at is not null
     or old.status::text not in ('scheduled', 'in_progress') then
    raise exception 'child_reparent_forbidden' using errcode = '42501';
  end if;

  v_actor_user_id := private.get_current_user_id();
  v_company_id := private.get_user_company_id();
  if v_actor_user_id is null or v_company_id is null then
    raise exception 'child_reparent_forbidden' using errcode = '42501';
  end if;
  if old.company_id is distinct from v_company_id::text then
    raise exception 'child_reparent_forbidden' using errcode = '42501';
  end if;
  if not private.current_user_can_edit_site_visit(
    old.company_id, v_old_opportunity_id, old.project_id, old.project_ref
  ) then
    raise exception 'child_reparent_forbidden' using errcode = '42501';
  end if;

  if v_new_opportunity_id is not null then
    select * into v_target
      from public.opportunities o
     where o.id = v_new_opportunity_id;
    if not found or v_target.company_id is distinct from v_company_id then
      raise exception 'child_reparent_forbidden' using errcode = '42501';
    end if;
    if v_target.archived_at is not null or v_target.deleted_at is not null then
      raise exception 'child_reparent_forbidden' using errcode = '42501';
    end if;
    if not private.user_can_edit_opportunity(v_actor_user_id, v_new_opportunity_id) then
      raise exception 'child_reparent_forbidden' using errcode = '42501';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.require_site_visit_child_company_match()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_parent_company_id text;
  v_parent_opportunity_id uuid;
begin
  select visit.company_id, visit.opportunity_id
    into v_parent_company_id, v_parent_opportunity_id
    from public.site_visits visit
   where visit.id = new.site_visit_id
   for key share;

  if not found then
    raise exception 'site_visit_child_parent_not_found'
      using errcode = '23503';
  end if;
  if new.company_id is distinct from v_parent_company_id then
    raise exception 'site_visit_child_company_mismatch'
      using errcode = '23514';
  end if;
  if new.opportunity_id is distinct from v_parent_opportunity_id then
    raise exception 'site_visit_child_opportunity_mismatch'
      using errcode = '23514';
  end if;

  return new;
end;
$function$
